import { advanceVok1, advanceVok2, recoverVok } from "./vok/rules";
import { advanceZef1, advanceZef2 } from "./zef/rules";

export interface WorldProtocol<WorldStateHandle = World> {
  reset(): WorldStateHandle;
  applyOperation(
    state: WorldStateHandle,
    operationDisplayName: string
  ): { success: true; newState: WorldStateHandle } | { success: false; error: string };
