  ): string;
  toAbstractSnapshot(state: WorldStateHandle): Record<string, string>;
}

function errorMessage(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

export const protocol: WorldProtocol = {
  reset(): World {
    return createInitialWorld();
  },

  applyOperation(
    state: World,
    operationDisplayName: string
  ): { success: true; newState: World } | { success: false; error: string } {
    try {
      let newState: World;
      switch (operationDisplayName) {
        case "advanceFen1":
          newState = advanceFen1(state);
          break;
        case "advanceFen2":
          newState = advanceFen2(state);
          break;
        case "advanceOsk1":
          newState = advanceOsk1(state);
          break;
        case "advanceTal1":
          newState = advanceTal1(state);
          break;
        case "advanceVok1":
          newState = advanceVok1(state);
          break;
        case "advanceVok2":
          newState = advanceVok2(state);
          break;
        case "recoverVok":
          newState = recoverVok(state);
          break;
        case "advanceZef1":
          newState = advanceZef1(state);
          break;
        case "advanceZef2":
          newState = advanceZef2(state);
          break;
        default:
          return {
            success: false,
            error: `Unknown operation: ${operationDisplayName}`,
          };
      }
      return { success: true, newState };
    } catch (error) {
      return { success: false, error: errorMessage(error) };
    }
  },

  getEntityState(state: World, entityDisplayName: string): string {
    switch (entityDisplayName) {
      case "Fen":
      case "fen":
        return state.fen;
      case "Osk":
      case "osk":
        return state.osk;
      case "Tal":
      case "tal":
        return state.tal;
      case "Vok":
      case "vok":
        return state.vok;
      case "Zef":
      case "zef":
        return state.zef;
      default:
        return "unknown";
    }
  },

  toAbstractSnapshot(state: World): Record<string, string> {
    return {
      Fen: state.fen,
      Osk: state.osk,
      Tal: state.tal,
      Vok: state.vok,
      Zef: state.zef,
    };
  },
};
